main(): Int64 {
    let catalog = TextCatalog()
    catalog.add(42)
    assert(catalog.at(0) == "42")
    assert(catalog.equalsEntries(["42"]))

    let before = catalog.snapshot()
    var rejected = false
    try {
        catalog.add(42, radix: 16)
